window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"wisdoms","number":393,"source":"حکمت 393.docx","mode":"whole-entry","parts":["حکمت 393\nمتن:\nوَ قَالَ (عليه السلام): خُذْ مِنَ الدُّنْيَا مَا أَتَاكَ، وَ تَوَلَّ عَمَّا تَوَلَّى عَنْكَ؛ فَإِنْ أَنْتَ لَمْ تَفْعَلْ، فَأَجْمِلْ فِي الطَّلَبِ.\nترجمه:\nامام(عليه السلام) فرمود: از دنيا همان قدر را بگير كه به سراغ تو مى آيد و از آنچه از تو روى گردانده روى بگردان (و به دنبال آن مشتاب) و اگر چنين نمى كنى لااقل در طلب دنيا به صورت معقول تلاش كن (و تندروى مكن).\nتفسیر:\n💠وَ قَالَ (علیه السلام): خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ\nاز دنیا همان قدر را بگیر که به سراغ تو مى آید.\n💠 وَ تَوَلَّ عَمَّا تَوَلَّى عَنْکَ\nو از آنچه از تو روى گردانده روى بگردان و به دنبال آن مشتاب،\n💠فَإِنْ أَنْتَ لَمْ تَفْعَلْ، فَأَجْمِلْ فِی الطَّلَبِ\nو اگر چنین نمى کنى لااقل در طلب دنیا به صورت معقول تلاش کن و تندروى مکن.\n🔻امیرالمومنین علیه السلام در این حکمت در مورد بهره گرفتن از دنیا سه دستور میدهند:\n1⃣ اگر میتوانید با دنیا زاهدانه برخورد کنید.\n2⃣ اگر میتوانید برای از دست رفتن دنیا، صبر به خرج بده.\n3⃣ اگر نمیتوانید زاهد و صبور باشید، لااقل با دنیا به زیبایی مواجه شو و میانه روی کنید.\n💠دربخش اول حکمت آمده :\nخُذْ مِنَ الدُّنْیَا مَا أَتَاکَ\nاز دنیا همان قدر را بگیر که به سراغ تو مى آید.\nامیرالمومنین علیه السلام درباب رزق و روزی مطالب فراوانی دارند.\nاساس مطالب درمورد رزق وروزی حکمت ۴۳۱:\nالرِّزْقُ رِزْقَانِ، طَالِبٌ وَ مَطْلُوبٌ\nروزى بر دو گونه است: یکى آن‏که به ‏دنبال انسان مى ‏آید و دیگر آن‏که انسان به‏ دنبال آن مى‏ رود.\nرزق طالب هم روزی های نانوشته ای است که خداوند برای انسان مقدر کرده است،\nهم رزق و روزی است که هر انسانى در شرایط معمولى با کسب و کار عادى و آبرومند به دست می آورد.\nزیاده روی بداست ،حرص ،جمع کردن،بخل بداست.وگرنه استفاده به اندازه رزق طالب و رزق مطلوب بسیار خوب است.کسب وکار باید آبرومند باشد،انسان تلاش کندو کارکندپول به دست بیاورد،برای رفاه خودش وخانواده اش خرج کند.\n✍️حقیقت زهد نیز همین بود که انسان حرص و طمع به دنیا نداشته باشد، وابسته ی به دست آوردن حجم بیشتری از کالای دنیا نباشد.\nلذا حضرت در توصیه ی اول به اصل زهد، قناعت و کفاف امر میکنند.\nپر واضح است که هرگز منظور امام  از  ” خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ ” این نیست که انسان در خانه خود بنشیند تا رزق و روزى اش به سراغ او بیاید این همان چیزى است که با صراحت در روایات از آن نهى شده است.  و ما مامور به کار هستیم.\n⏪منظور آن است که اصرار بر افزودن مال و ثروت در جایى که اسبابش فراهم نیست نداشته باشد چراکه:\nزیاده روی ها حداقل سه آفت ومشکل برای شما ایجاد میکند:\n1⃣هم مشقت زیادى را بر انسان تحمیل مى کند.\nدرروایت داریم که خداوند به دنیا وحی کرد که اگر کسی دنبال توبود از دست آن فرار کن اورابه بردگی بکش بارروی دوش اوبگذار.\n2⃣ ممکن است آلوده انواع گناهان و انحراف از مسیر شرع شود.\nکسی که همه ی همتش شد پول درآوردن برای به دست آوردن پول حاضر است،هرکاری بکند حتی دین فروشی.\n3⃣ اگر به آن نرسد زبان به ناشکرى و کفران بگشاید.\nاگر انسان اعتدال را رعایت کرد دیگر به این آفت‌ها دچار نخواهد شد.\n✳️خیالمان از روزی راحت باشد:\n🔻در حکمت ۳۶۵ از حضرت سوال شد:\nلَوْ سُدَّ عَلَى رَجُلٍ بَابُ بَیْتِهِ وَ تُرِکَ فِیهِ، مِنْ أَیْنَ کَانَ یَأْتِیهِ رِزْقُهُ؟ فَقَالَ (علیه السلام): مِنْ حَیْثُ یَأْتِیهِ أَجَلُه.\nاز امام علیه السلام پرسیدند: اگر درِ خانه کسى را به روى او ببندند و در همان جا محبوس گردد از کجا روزى اش مى رسد؟ امام علیه السلام در پاسخ فرمود: از همان جا که اجل به سراغ او مى آید!\n💠خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ\nآنچه که از دنیا به سمت تو میآیدآن رابگیر\n💠وَ تَوَلَّ عَمَّا تَوَلَّى عَنْکَ\nو از آنچه از تو روى گردانده روى بگردان و به دنبال آن مشتاب.\n◀️در مسیر زندگی، خیلی اوقات انسان برای رسیدن به اهداف و خواسته هایش تلاش میکند ولی به هر دلیلی به خواسته هایش نمیرسد؛ یا به خواسته هایش میرسد ولی بعد از مدتی آنها را از دست میدهد.\n↩️یا پست است مقام، پول،یاکلا نمیرسد یا اگر رسید دنیا دولت است دست به دست میشود،از این نفربه نفربعدی منتقل می‌کند.مواجه ما با این عادت دنیا چه باشد؟دنیا کارش این است که ازکسی بگیرد و به دیگری بدهد.جنس،مال،قدرت در دست هیچ کسی ثابت نیست.اگرذات دنیا این است اینجا دو راه دارد:\n1⃣ یا نشستن و گریستن بر آنچه از دست رفته، و حسرت آنها را خوردن و افسردگی بعد از شکست.\n2⃣یا دل از آنها بریدن، چشم از آنها برداشتن و ادامه دادن مسیر به سمت اهداف جدید؛ با تجربه ای بیشتر.\n✍️ به فرایندِ گیر نکردن پشت دست انداز مشکلات؛ صبر میگویند.\nوقتی سدی ایجاد میشود چیزی را از تو میگیرند،این توقف نکردن می‌شود صبر. اگر دائم گریه وزاری کردید این صبر نیست،اگر گذشتید حالت صبر است.\n❇️هر چه از تو روی گرداند، از آن روی بگردان:\nقرآن کریم میفرماید:\nلِکَیْلَا تَأْسَوْا عَلَىٰ مَا فَاتَکُمْ وَ لَا تَفْرَحُوا بِمَا آتَاکُمْ.\nبر آنچه از دست شما رفت، تأسف نخورید، و بر آنچه به شما عطا کرده است، شادمان و دلخوش نشوید.\n⏪اگرچیزی دادندالحمدالله نعمتی است که درپس آن وظیفه است اگرچیزی گرفتند الحمدالله نعمت داده بودندو گرفتند مسیرطبیعی دنیا همین است .میدهند و میگیرند پس افسوس خوردن و حسرت خوردن ندارد.\n✍️ دل بریدن از آنچه از دست انسان رفته است و صبر بر آن دومین توصیه حضرت است.\n🔻در نامه ۴۷ که وصیت نامه هنگام شهادت حضرت است فرمود:\nأُوصِیکُمَا بِتَقْوَى اللَّهِ، وَ أَلَّا تَبْغِیَا الدُّنْیَا وَ إِنْ بَغَتْکُمَا\nمن شما را به تقوا و پرهیزکارى توصیه مى کنم و سفارش مى کنم و در پى زرق و برق دنیا نباشید، هرچند دنیا به سراغ شما بیاید\nوَ لَا تَأْسَفَا عَلَى شَیْءٍ مِنْهَا زُوِیَ عَنْکُمَا\nو بر آنچه از دنیا از دست مى دهید تأسف نخورید.\n✳️دنیا مثل بدهکار فراری است:\nمثال ابن ابی الحدید:\nاجْعَلِ الدُّنْیَا کَغَرِیمِ السُّوءِ\nدنیا را مانند بدهکار بد قرار بده!\nحَصَلَ مِنْهُ مَا یَرْضَخُ لَکَ بِهِ\nمقدار کمی را که به تو می‌پردازد بپذیر\n\n◀️ این نگاه رامقایسه کنید با کسانی که میخواهندبه کل دنیا برسند،میخواهند همه ی آن بدیهیشان را از دنیا بگیرند. تازه آرزوهای بلند و بالا هم دارند اینها گرفتارند. ‌\n🔻حضرت فرمودند:اگر چیزی هم دنیا از توگرفته شد ناراحت نباش .\nاین قاعده اگر درذهن انسان باشد درکم وزیاد شدن دنیا خیلی نگران وافسرده نخواهد شد.\nبخش اول :خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ ،\nبخش دوم: وَ تَوَلَّ عَمَّا تَوَلَّى عَنْکَ\n  بخش سوم: فَإِنْ أَنْتَ لَمْ تَفْعَلْ، فَأَجْمِلْ فِی الطَّلَبِ\nو اگر چنین نمى کنى لااقل در طلب دنیا به صورت معقول تلاش کن و تندروى مکن.\nحضرت بعد از بیان دو نقطه ی ایده آل که زهد و تاسف نخوردن بر دنیاست؛\nبرای  کسانی که توان رسیدن به قله را ندارند؛ پیشنهاد دیگری مطرح میکنند و آن نیز “میانه روی در دنیاست”\nجمله ی ” فَإِنْ أَنْتَ لَمْ تَفْعَلْ” دو مصداق دارد:\n1⃣ کسانی که اصرار دارند وضعیت مادی آنها خوب شود، علاقه به ثروت دارند.\n2⃣ کسانی که توان تحمل سختی ها را ندارند، صبر بر مشکلات ندارند.\n✍️هیچ جای شک و شبهه نیست که اتفاقا اکثر افراد جامعه جزء همین دو دسته به حساب می آیند؛ لذا حضرت برای اینکه اینها نیز از مسیر زندگی مومنانه خارج نشوند میفرماید ” میانه روی اقتصادی” داشته باشید.\nاگر اصرار دارى بر مال و جاه خود بیفزایى، تندروى مکن; عاقلانه تلاش کن و آلوده گناهان مشو.\n⏪عقل به تو می‌گوید: پول دربیاور ولی پول مردم را نخور،عقل به تو میگوید پول در بیاور ولی سلامتیت مهمتر از پول است،پول در بیاور ولی خرج کن ذخیره نکن خساست به خرج نده حضرت فرمودند:مسیر اعتدال،مسیر عقل را در کسب وخرج در هر دو پیاده کنید.زاهد نشدید صبور نشدید طوری نیست ولی حداقل موازین شرع را انسان رعایت کند.این میانه روی اقتصادی درمشی نهج البلاغه درمشی اسلام است .\n❇️معنای اجمال در طلب:\nلفظ ” فَأَجْمِلْ فِی الطَّلَبِ” از ماده ی جمال و زیبایی است ولی در حکمت مورد نظر از آنجایی که اعتدال حد وسط افراط و تفریط است و اعتدال همیشه زیباست؛ در معنای حکمت لفظ جمال را به معنای میانه روی ترجمه کردیم.\n❇️عاقل، کارگر دنیا نمیشود:\nحضرت فرمودند: عاقلانه رفتارکنیدحداقلها را رعایت کنید‌یکی از اموری که انسانهای عاقل رعایت می‌کنند برده دنیا نمیشوندبند بردگی به گردن خودشان نمی اندازند.\n\n🔻پیامبر اکرم صَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم میفرمایند:\nپیامبر صلوات الله علیه در حالى که غمگین بود از منزل خارج شد فرشته اى خدمت آن حضرت آمد در حالى که کلید گنج هاى زمین را در دست داشت عرض کرد: اى محمّد! این کلید گنج هاى زمین است پروردگارت مى فرماید: آن ها را بگشا و هرچه مى خواهى بردار بى آن که چیزى از مقام تو نزد من کم شود.\n🔻 فَقَالَ رَسُولُ اللَّهِ(صلى الله علیه وآله) الدُّنْیا دَارُ مَنْ لاَ دَارَ لَهُ وَ لَهَا یجْمَعُ مَنْ لاَ عَقْلَ لَهُ  \nفرمود: دنیا خانه کسى است که خانه دیگرى ندارد و آن را کسى گردآورى مى کند که عقلى ندارد.\n \nانسان عاقل برای دنیا چیزی جمع نمیکند،برای خرج ومخارج خودش برای زندگی دنیا استفاده می‌کند، پول به دست می آورد ولی جمع نمیکند، زیاده روی نمی کند.\n✍️با دنیا باید عاقلانه و با اعتدال برخورد کرد نه اینکه دست انداخت و همه ذخائر دنیا را برای خود برداشت، که این به زیان انسان خواهد بود.\n✳️طلب زیبای رزق، سفارش جبرئیل به پیامبر:\n🔻پیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nألا وإنّ الرُّوحَ الأمینَ نَفَثَ فیرُوعِی أ نّهُ لَن تَمُوتَ نفسٌ حتّى تَستَکمِلَ رِزقَها\nهمانا روح الامین در دلم چنین افکند که هیچ کسی نمیرد تا روزى اش را به طور کامل دریافت کند.\nفاتَّقُوا اللّه و أجمِلُوا فی الطَّلَبِ\nپس، از خدا بترسید و در طلب روزى آرام و معتدل باشید.\n⏪اعتدال ومیانه روی درکسب پول داشته باشید یک حدو حدودی را برای خودتان رعایت کنید،یک اعتدالی یک مرزی را که از دین خارج نشوید را برای خودتان قرار بدهید.نفس انسان سرکش است دنیا طلب است باید افسار نفس راکشید اورایک جایی الزام کردبه دست کشیدن از دنیا.\n✅افسار مرکب دنیا طلبی را باید کشید:\nنامه ۳۱:\nوَ اعْلَمْ یَقِیناً أَنَّکَ لَنْ تَبْلُغَ أَمَلَکَ\nو به یقین بدان هرگز به همه آرزوهایت دست نخواهى یافت\n وَ لَنْ تَعْدُوَ أَجَلَکَ  \nو بیش از آنچه مقرر شده عمر نمى کنى\nوَ أَنَّکَ فِی سَبِیلِ مَنْ کَانَ قَبْلَکَ  \nو تو در همان مسیرى هستى که پیشینیان تو بودند،آنها رفتند و تو هم خواهى رفت\nفَخَفِّضْ فِی الطَّلَبِ وَ أَجْمِلْ فِی الْمُکْتَسَبِ\nحال که چنین است، در به دست آوردن دنیا زیاده روى مکن و در کسب و کار میانه رو باش\n📚این نامه 31 ،نامه ی تربیتی است امیرالمومنین علیه السلام به امام مجتبی علیه السلام میفرمایند:وبه همه ی ما میگویند به بچه هاتون یاد بدهید و خودتان یاد بگیرید اولا رزق ثابت است ثانیا اجل مقدر است، شما نمی توانید به همه ی آرزوها برسید درست زندگی کنید، درست کسب وکار کنید ،دزدی نکنید، برای رسیدن به دنیا چیزی که حق نیست را نگیر.پس قشنگ زندگی کنید،زندگی زیبا می‌تواند آینده تورا ،بهشت تو را تضمین کند.\n✳️ تنها راه آرامش در زندگی اجتماعی و شخصی، عمل به ” فَأَجْمِلْ فِی الطَّلَبِ” است:\nمشکلات عظیمى که در دنیاى دیروز و امروز و فردا وجود داشته، دارد و خواهد داشت؛ ناشى از حرص حریصان و دنیاپرستان است که به سهم و حق خود از دنیا قانع نیستند و اصرار دارند از دیگران بگیرند و به خود بیفزایند.\nسرچشمه جنگ ها و نزاع ها و بسیارى از پرونده هاى سنگین دادگاه ها همین حرص دنیا و بیش از حق خود طلبیدن است.\nاگر به دستورى که حضرت عمل شود آتش جنگ ها خاموش مى گردد و پرونده هاى دادگاه ها بسته خواهد شد\n🔹شاعر عرب پایان مى گوید:\nیا حَرِیصاً قَطَع الأیّامَ فِى * بُؤسِ عَیْش وَعَناء و تَعَب\nاى کسى که تمام روزها را در ناراحتى و رنج و تعب براى افزودن مال و ثروت، مى گذرانى!\nلَیْسَ یَعدُوکَ مِنَ الرِّزقِ الّذِى * قَسَم اللّهُ، فأجْمِل فى الطَّلَب\nبدان آن رزقى که خدا براى تو مقرر کرده است از تو دریغ نخواهد شد بنابراین در طلب دنیا معقولانه رفتار کن\n✍️به اندازه ای که نیاز دارید تلاش کنید نه به اندازه آرزوی که درسرمیپرورانید .\n✳️دنیا طلب ها را در یک مورد اسوه بگیرید:\n📚شیخ صدوق در امالی روایت نقل میکند: المسیحُ علیه السلام : یا بَنِی إسرائیلَ ، لا تَأسَوا على ما فاتَکُم مِن دُنیاکُم إذا سَلِمَ دِینُکُم\nاى بنى اسرائیل! هر گاه دینتان سالم بود ، براى از دست دادن دنیاتان افسوس نخورید\nکما لا یَأسى أهلُ الدنیا على ما فاتَهُم مِن دِینِهِم إذا سَلِمَتْ دُنیاهُم\nهمچنان که دنیا پرستان هر گاه دنیایشان سالم باشد ، براى از دست دادن دینشان اندوهى به خود راه نمى دهند.\n✍️ ما حداقل به اندازه ی دنیا طلب ها متعصب باشیم.\n آنها وقتی دنیایشان رو به راه باشد برای دین دل نمیسوزانند، ما هم وقتی دینمان درست و سالم بود برای دنیا دل نسوزانیم و به حد کفاف آن قانع باشیم.\n🔻”اَلْإِجْمَالَ فِی اَلطَّلَبِ”، از اصطلاحات پر کاربرد روایات:\n✅اجمال فی الطلب عفت است:\nامام مجتبی علیه السلام: لاَ تُجَاهِدِ اَلطَّلَبَ جِهَادَ اَلْغَالِبِ\nنه چون پیروزمندان در طلب دنیا بکوش کسانی که مزه دنیا زیر دندانشان رفته و در طلب کسب بیشتر اند.\nوَ لاَ تَتَّکِلْ عَلَی‌ اَلْقَدَرِ اِتِّکَالَ اَلْمُسْتَسْلِمِ\nنه مانند تسلیم‌شدگان به تقدیر تکیه کن و بیماری را پیشه نکن .\nفَإِنَّ اِبْتِغَاءَ اَلْفَضْلِ مِنَ اَلسُّنَّهِ\nکه رفتن دنبال فضل و احسان خدا  سنت و قانون هستی است.\nوَ اَلْإِجْمَالَ فِی اَلطَّلَبِ مِنَ اَلْعِفَّهِ  \nاعتدال در طلب روزی نشانه ی عفت است.\n✳️خودنگهداری در برابر تمایلات:\nعفت خیلی مقام بزرگی است عفت بسیار جایگاه رفیعی است اگر کسی می‌خواهد به عفت برسد یکی از راه‌ها این است عفت درمقابل مالی یعنی به حداقل‌ها اکتفا کنید همینکه زیاده روی نکنید، کافیه پول دارید دنبال پول هم هستید ،حضرت فرمودند طوری نیست اجمال داشته باشید خطوط قرمز را ردنکنید این یک مدل از عفاف اقتصادی است.\n❇️اجمال فی الطلب نشانه ی ایمان است:\nامیرالمومنین علیه السلام:\n سِتَّهٌ تُخْتَبَرُ بِهَا دِینُ اَلرَّجُلِ: اَلْوَرَعُ، وَ اَلتَّقْوَی‌، وَ صِدْقُ اَلْیَقِینِ، وَ مُجَاهَدَهُ اَلْهَوَی‌، وَ اَلْعِفَّهُ، وَ اَلْإِجْمَالُ فِی اَلطَّلَبِ . دین مردم را آزمود: ورع ،تقوا، یقین صادقانه، مبارزه با نفس، عفت، و میانه روی در خواستن.\nیکی از مواردی که انسان می‌تواند دین خود را بسنجدآن است که شما چقدر اجمال فی الطلب دارید؟چقدر میانه روی دارید؟چقدر از حرص دور هستید؟هرچه کمتر باشد دینداری شما بزرگتر وغنی تر است.باید با پنبه سردنیا رابرید با یداز دنیا بهره برداری کنیم نه با سروصدا نه باحرص نه طوری که اومارا به بندگی بکشد.\n✳️باید با پنبه سر دنیا را برید و بهره را از او گرفت:\nامیرالمومنین علیه السلام :\nاَلدُّنْیَا دُوَلٌ فَاطْلُبْ حَظَّکَ مِنْهَا بِإِجْمَالِ اَلطَّلَبِ\nدنیا دست بدست میچرخد تو بهره خود را از آن با آرامی‌ جستجو کن و حریص مباش.\n✍️ کسانی که میخواهند هیجانی و بیش از حد از دنیا بهره ببرند، دنیا متوجه میشود و با آنها گلاویز میشود. ولی کسانی که آهسته به سراغ دنیا میروند، میتوانند همه بهره شان را بی درد سر از دنیا بگیرند.\n✳️اجمال فی الطلب در سیره امیرالمومنین:\nدرنامه ۴۵ به عثمان بن حنیب:\nوَ لَوْ شِئْتُ لاَهْتَدَیْتُ اَلطَّرِیقَ إِلَى مُصَفَّى هَذَا اَلْعَسَلِ وَ لُبَابِ هَذَا اَلْقَمْحِ وَ نَسَائِجِ هَذَا اَلْقَزِّ  \nفکر نکنید من قادر به تحصیل لذت هاى دنیا نیستم. به خدا سوگند اگر مى خواستم مى توانستم از عسل مصفا و مغز گندم و بافته هاى ابریشم براى خود بهترین غذا و لباس را تهیّه کنم\nوَ لَکِنْ هَیْهَاتَ أَنْ یَغْلِبَنِی هَوَایَ وَ یَقُودَنِی جَشَعِی إِلَى تَخَیُّرِ اَلْأَطْعِمَهِ\nاما هیهات که هواى نفس بر من چیره شود و حرص و طمع مرا وادار به انتخاب طعام هاى لذیذ نماید.\n✍️ حضرت میتوانست بهترین ها را داشته باشد، آن هم از راه حلال و درست ولی اراده کرد میانه روی و زهد در مسیر دنیا را در پیش بگیرد.\n✅نکته:\nباید در به دست آوردن دنیا، زیبایی را لحاظ کرد:\nاگر چه در ابتدای بحث بیان شد که در این حکمت اجمال را به معنای اعتدال میگیریم؛ ولی نباید غافل بود که از جهت لغوی این لفظ به معنای زیبایی است؛ پس باید در طلب دنیا، دنیا طلب زیبا بود.\nکسب زیبا به معنای تلاش برای به دست آوردن روزی از راه‌های حلال، معقول، و با حفظ کرامت انسانی است.\nاین نوع کسب، تنها برای انباشت ثروت نیست، بلکه برای تأمین نیازهای مشروع خود و خانواده، استقلال اقتصادی و قوت گرفتن برای عبادت خداوند است.\n✳️مال حلال، زیبا است:\nکسب وکار و در آمدتان و رزق و روزیتان زیبا باشد. از جایی پول به دست آورید که زیبا باشد. طوری خرج کنید که زیبا باشد.هرکاری که باعث زشتی میشود از خودتان دور کنید.هرمدل پول به دست آوردن که زشت است از تو باید دور باشد. محرمات، مکاسب محرمه زشت است ربا، قمار،زشت است دنبالشان نروید.هرچیزی که زشت باشد دراین دایره جایی ندارد.حضرت فرمودند کار کنیدوظیفه تان است ولی پول قشنگ به دست بیارید.\nقرآن کریم میفرماید:\nیَا أَیُّهَا النَّاسُ کُلُوا مِمَّا فِی الْأَرْضِ حَلَالًا طَیِّبًا\nای مردم! از آنچه در زمین است حلال و پاکیزه بخورید.\n❇️تجارت، بعد از انجام تکالیف عبادی زیباست:\nقرآن کریم در سوره جمعه میفرماید: فَإِذَا قُضِیَتِ الصَّلَاهُ فَانْتَشِرُوا فِی الْأَرْضِ وَابْتَغُوا مِنْ فَضْلِ اللَّهِ\nپس هنگامی که نماز اتمام یافت، در زمین پراکنده شوید و از فضل خدا روزی بجویید.\n⏪پول زیبا پولی است که شما وظیفه ی شرعیتان را انجام بدهیدحالا دنبال کاربردی کاریه انجام می‌دهید پولش زیباست پولش تربیت فرزند شما را به درستی انجام میدهد.\n✍️ این آیه الگویی زیبا ارائه می‌دهد.\nاولویت با عبادت است و سپس تلاش برای روزی در چارچوب رضایت خدا.\n✅کسب در آمدی که با یاد خدا باشد زیباست:\nقرآن کریم در سوره نور میفرماید: رِجَالٌ لَّا تُلْهِیهِمْ تِجَارَهٌ وَلَا بَیْعٌ عَن ذِکْرِ اللَّهِ  \nمردانی که هیچ تجارت و خرید و فروشی آنان را از یاد خدا غافل نمی‌کند…\n◀️کاری که همراه باذکرباشد.پول به دست آوردن که همره با توجه به خدا باشد میشود پول به دست آوردن زیبا\n✍️ نمیفرماید آنها اهل کار نیستند، میفرماید کار آنها را از ذکر و یاد خدا غافل نمیکند.\n✳️رزقی که از طریق جوانمردان برسد زیباست:\nباجوانمردها معاشرت کنید.باجوانمردها دادو ستد کنید.\nحکمت ۶۶:\nفَوْتُ الْحَاجَهِ، أَهْوَنُ مِنْ طَلَبِهَا إِلَى غَیْرِ أَهْلِهَا\nاز دست رفتن حاجت بهتر از طلب کردن آن از نااهلان است!\n⏪اگر می‌خواهید پول زیبا داشته باشید قرضم که خواستید بگیرید از یک انسان جوانمرد بگیرید ولی اگر حق خودتان را از ناجوانمرد گرفتید این به آن زیبایی که باید باشد نیست.\n✅رزقی که دسترنج باشد، زیباست:\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nأطیَبُ الکَسبِ عَمَلُ الرجُلِ بیَدِهِ\nپاکترین کسب و درآمد، دسترنج آدمى است.\n🔺در روایت آمده است: از معجزه زیباتر، کار کردن است:\n📚مرحوم مجلسی در بحار نقل میکند:\nرُویَ أنَّ حَوارِیِّی عیسى علیه السلام کانوا إذا جاعُوا قالوا : یا رُوحَ اللّه جُعْنا ، فَیَضرِبُ بیَدِهِ علَى الأرضِ ـ\nروایت شده است که حواریان عیسى علیه السلام هر گاه گرسنه مى شدند، مى گفتند: یا روح اللّه ! گرسنه شده ایم. پس، عیسى علیه السلام با دست خود به زمین، چه دشت بود و چه کوه، مى زد و براى هر یک از حواریان دو گرده نان بیرون مى آورد، که آنها را مى خوردند.\nفإذا عَطِشُوا قالوا : یا رُوحَ اللّه عَطِشْنا ، فَیَضرِبُ بیَدِهِ على الأرضِ ـ سَهلاً کان أو جَبَلاً ـ فَیُخرِجُ ماءً فَیَشرَبُونَ  \nو هر گاه تشنه مى شدند، مى گفتند: یا روح اللّه ! تشنه شده ایم و آن حضرت با دستش به زمین، خواه دشت بود یا کوه، مى زد و آب بیرون مى آورد و حواریان مى نوشیدند..\nقالوا : یا رُوحَ اللّه ، مَن أفضَلُ مِنّا ؟ إذا شِئنا أطعَمتَنا ، و إذا شِئنا سَقَیتَنا ، و قد آمَنّا بکَ و اتَّبَعناکَ !\nآنها گفتند: یا روح اللّه ! چه کسى از ما برتر است که هر گاه مى خواهیم غذایمان مى دهى و هر گاه مى خواهیم آبمان مى نوشانى در حالى که همه ما به تو ایمان آورده ایم و پیرویت مى کنیم؟\n قالَ : أفضَلُ مِنکُم مَن یَعَملُ بیَدِهِ ، و یَأکُلُ مِن کَسبِهِ  \nعیسى علیه السلام فرمود: برتر از شما، کسى است که با دست خود کار کند و از کسب خودش بخورد.\nفصاروا یَغسِلُونَ الثِّیابَ بالکِراءِ\nاز آن پس حواریان رخت مى شستند و اجرت مى گرفتند.\n✍️پولی که از دسترنج انسان باشد زیباست ولی پولی که باد آورده باشدزیبایی ندارد.\n✳️ رزقی که انسان برای آن  جانش را به خطر نیندازد زیباست:\nمصداقش را درروایات داریم\nامیرالمومنین علیه السلام:\nمَا أَجْمَلَ فِی اَلطَّلَبِ مَنْ رَکِبَ اَلْبَحْرَ لِلتِّجَارَهِ.\nکسی که برای تجارت از راه دریا اقدام کند، در کسب روزی اعتدال به خرج نداده است\n✍️ در گذشته سفرهای دریایی سخت و خطرناک بود، ماهها می رفتند و زن و فرزند، در انتظار و دلهره بودند. حضرت می فرماید این سفرها برای کسب در آمد مناسب نیست.\n❇️رزقی که در وطن به دست بیاید زیباست:\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nأربَعهٌ مِن سَعادَهِ المَرءِ .\nچهار چیز از خوشبختى مرد است\nالخُلَطاءُ الصّالِحُونَ\nهمنشینان شایسته\nو الوَلَدُ البارُّ\nفرزند نیکوکار،\nو المَرأهُ المُؤاتِیَهُ\nزن سازگار،\nو أن تَکونَ مَعِیشَتُهُ فی بَلَدِهِ\nو این که محل کسب او در شهر خودش باشد.\n\n✍️ رزق اگر به دست بیاید ولی آبروی انسان را در معرض خطر قرار دهد، زیبا نیست.\n \n✅کسب  در آمد از طریق ریاست طلبی زیبا نیست:!\nامام صادق علیه السلام:\nمَلْعُونٌ مَنْ تَرَأَّسَ\nملعون است کسى‌که ریاست به خود بندد\nمَلْعُونٌ مَنْ هَمَّ بِهَا   \nملعون است کسى‌که دنبال رسیدن به ریاست باشد\nمَلْعُونٌ مَنْ حَدَّثَ بِهَا نَفْسَهُ\nملعون است کسى که به فکر آن باشد.\nدارد درس می‌خواند تا فردا به پست و‌مقامی برسد.پست ومقام و مسئولیت وظیفه است نباید دنبال آن برود پولی هم که از این راه به دست می آورد زیبا نیست.\n🔹 وقتی امیرالمومنین علیه السلام فرزندان عمویش عباس را مسئولیت داد، مالک اشتر اعتراض کرد که اگر قصه فامیل بازی است، چرا ما عثمان را کشتیم.\n🔹حضرت با ملاطفت به مالک فرمود من که فرزندان خودم را به مسئولیت نگمارده ام و علت اینکه به فرزندان عباس مسئولیت دادم این است که اولا افراد شایسته ای هستند، ثانیا در دوران خلفا به آنها ظلم شد، چون فامیل ما بودند، ثالثا اگر کسی بهتر میشناسی بیاور تا جابجا کنم.\nامیرالمومنین علیه‌السلام فرمود:\nاِنِّی سَمِعْتُ اَلْعَبَّاسَ یَطْلُبُ مِنْ رَسُولِ اَللَّهِ صَلَّى اَللَّهُ عَلَیْهِ وَ آلِهِ اَلْإِمَارَهَ مِرَاراً  \nمن مکرر از عمویم عباس شنیدم که از پیامبر طلب مسئولیت میکرد.\nفَقَالَ لَهُ رَسُولُ اَللَّهِ صَلَّى اَللَّهُ عَلَیْهِ وَ آلِهِ یَا عَمِّ إِنَّ اَلْإِمَارَهَ إِنْ طَلَبْتَهَا وُکِّلْتَ إِلَیْهَا وَ إِنْ طَلَبَتْکَ أُعِنْتَ عَلَیْهَا\nپیامبر صلوات الله علیه و آله فرمود ای عمو حکومت را اگر طلب کنی به همان حکومت واگذار میشوی و اگر او تو را طلب کند خداوند در آن کار به تو یاری می‌رساند.\n✍️باید برای به دست آوردن رزق زیبا منتظر بود تا با توجه به تخصص فرد به او پیشنهاد پست و مقامی پیشنهاد بشود، وگرنه کسی که مدام دنبال رسیدن به جایگاه بالایی است آن پولی که بدست می آورد پول زیبایی نیست.\n\nغفر الله لی و لکم، الحمدلله رب العالمین\n💠وَ قَالَ (علیه السلام): خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ\nاز دنیا همان قدر را بگیر که به سراغ تو مى آید.\n💠 وَ تَوَلَّ عَمَّا تَوَلَّى عَنْکَ\nو از آنچه از تو روى گردانده روى بگردان و به دنبال آن مشتاب،\n💠فَإِنْ أَنْتَ لَمْ تَفْعَلْ، فَأَجْمِلْ فِی الطَّلَبِ\nو اگر چنین نمى کنى لااقل در طلب دنیا به صورت معقول تلاش کن و تندروى مکن.\n🔻امیرالمومنین علیه السلام در این حکمت در مورد بهره گرفتن از دنیا سه دستور میدهند:\n1⃣ اگر میتوانید با دنیا زاهدانه برخورد کنید.\n2⃣ اگر میتوانید برای از دست رفتن دنیا، صبر به خرج بده.\n3⃣ اگر نمیتوانید زاهد و صبور باشید، لااقل با دنیا به زیبایی مواجه شو و میانه روی کنید.\n💠دربخش اول حکمت آمده :\nخُذْ مِنَ الدُّنْیَا مَا أَتَاکَ\nاز دنیا همان قدر را بگیر که به سراغ تو مى آید.\nامیرالمومنین علیه السلام درباب رزق و روزی مطالب فراوانی دارند.\nاساس مطالب درمورد رزق وروزی حکمت ۴۳۱:\nالرِّزْقُ رِزْقَانِ، طَالِبٌ وَ مَطْلُوبٌ\nروزى بر دو گونه است: یکى آن‏که به ‏دنبال انسان مى ‏آید و دیگر آن‏که انسان به‏ دنبال آن مى‏ رود.\nرزق طالب هم روزی های نانوشته ای است که خداوند برای انسان مقدر کرده است،\nهم رزق و روزی است که هر انسانى در شرایط معمولى با کسب و کار عادى و آبرومند به دست می آورد.\nزیاده روی بداست ،حرص ،جمع کردن،بخل بداست.وگرنه استفاده به اندازه رزق طالب و رزق مطلوب بسیار خوب است.کسب وکار باید آبرومند باشد،انسان تلاش کندو کارکندپول به دست بیاورد،برای رفاه خودش وخانواده اش خرج کند.\n✍️حقیقت زهد نیز همین بود که انسان حرص و طمع به دنیا نداشته باشد، وابسته ی به دست آوردن حجم بیشتری از کالای دنیا نباشد.\nلذا حضرت در توصیه ی اول به اصل زهد، قناعت و کفاف امر میکنند.\nپر واضح است که هرگز منظور امام  از  ” خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ ” این نیست که انسان در خانه خود بنشیند تا رزق و روزى اش به سراغ او بیاید این همان چیزى است که با صراحت در روایات از آن نهى شده است.  و ما مامور به کار هستیم.\n⏪منظور آن است که اصرار بر افزودن مال و ثروت در جایى که اسبابش فراهم نیست نداشته باشد چراکه:\nزیاده روی ها حداقل سه آفت ومشکل برای شما ایجاد میکند:\n1⃣هم مشقت زیادى را بر انسان تحمیل مى کند.\nدرروایت داریم که خداوند به دنیا وحی کرد که اگر کسی دنبال توبود از دست آن فرار کن اورابه بردگی بکش بارروی دوش اوبگذار.\n2⃣ ممکن است آلوده انواع گناهان و انحراف از مسیر شرع شود.\nکسی که همه ی همتش شد پول درآوردن برای به دست آوردن پول حاضر است،هرکاری بکند حتی دین فروشی.\n3⃣ اگر به آن نرسد زبان به ناشکرى و کفران بگشاید.\nاگر انسان اعتدال را رعایت کرد دیگر به این آفت‌ها دچار نخواهد شد.\n✳️خیالمان از روزی راحت باشد:\n🔻در حکمت ۳۶۵ از حضرت سوال شد:\nلَوْ سُدَّ عَلَى رَجُلٍ بَابُ بَیْتِهِ وَ تُرِکَ فِیهِ، مِنْ أَیْنَ کَانَ یَأْتِیهِ رِزْقُهُ؟ فَقَالَ (علیه السلام): مِنْ حَیْثُ یَأْتِیهِ أَجَلُه.\nاز امام علیه السلام پرسیدند: اگر درِ خانه کسى را به روى او ببندند و در همان جا محبوس گردد از کجا روزى اش مى رسد؟ امام علیه السلام در پاسخ فرمود: از همان جا که اجل به سراغ او مى آید!\n💠خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ\nآنچه که از دنیا به سمت تو میآیدآن رابگیر\n💠وَ تَوَلَّ عَمَّا تَوَلَّى عَنْکَ\nو از آنچه از تو روى گردانده روى بگردان و به دنبال آن مشتاب.\n◀️در مسیر زندگی، خیلی اوقات انسان برای رسیدن به اهداف و خواسته هایش تلاش میکند ولی به هر دلیلی به خواسته هایش نمیرسد؛ یا به خواسته هایش میرسد ولی بعد از مدتی آنها را از دست میدهد.\n↩️یا پست است مقام، پول،یاکلا نمیرسد یا اگر رسید دنیا دولت است دست به دست میشود،از این نفربه نفربعدی منتقل می‌کند.مواجه ما با این عادت دنیا چه باشد؟دنیا کارش این است که ازکسی بگیرد و به دیگری بدهد.جنس،مال،قدرت در دست هیچ کسی ثابت نیست.اگرذات دنیا این است اینجا دو راه دارد:\n1⃣ یا نشستن و گریستن بر آنچه از دست رفته، و حسرت آنها را خوردن و افسردگی بعد از شکست.\n2⃣یا دل از آنها بریدن، چشم از آنها برداشتن و ادامه دادن مسیر به سمت اهداف جدید؛ با تجربه ای بیشتر.\n✍️ به فرایندِ گیر نکردن پشت دست انداز مشکلات؛ صبر میگویند.\nوقتی سدی ایجاد میشود چیزی را از تو میگیرند،این توقف نکردن می‌شود صبر. اگر دائم گریه وزاری کردید این صبر نیست،اگر گذشتید حالت صبر است.\n❇️هر چه از تو روی گرداند، از آن روی بگردان:\nقرآن کریم میفرماید:\nلِکَیْلَا تَأْسَوْا عَلَىٰ مَا فَاتَکُمْ وَ لَا تَفْرَحُوا بِمَا آتَاکُمْ.\nبر آنچه از دست شما رفت، تأسف نخورید، و بر آنچه به شما عطا کرده است، شادمان و دلخوش نشوید.\n⏪اگرچیزی دادندالحمدالله نعمتی است که درپس آن وظیفه است اگرچیزی گرفتند الحمدالله نعمت داده بودندو گرفتند مسیرطبیعی دنیا همین است .میدهند و میگیرند پس افسوس خوردن و حسرت خوردن ندارد.\n✍️ دل بریدن از آنچه از دست انسان رفته است و صبر بر آن دومین توصیه حضرت است.\n🔻در نامه ۴۷ که وصیت نامه هنگام شهادت حضرت است فرمود:\nأُوصِیکُمَا بِتَقْوَى اللَّهِ، وَ أَلَّا تَبْغِیَا الدُّنْیَا وَ إِنْ بَغَتْکُمَا\nمن شما را به تقوا و پرهیزکارى توصیه مى کنم و سفارش مى کنم و در پى زرق و برق دنیا نباشید، هرچند دنیا به سراغ شما بیاید\nوَ لَا تَأْسَفَا عَلَى شَیْءٍ مِنْهَا زُوِیَ عَنْکُمَا\nو بر آنچه از دنیا از دست مى دهید تأسف نخورید.\n✳️دنیا مثل بدهکار فراری است:\nمثال ابن ابی الحدید:\nاجْعَلِ الدُّنْیَا کَغَرِیمِ السُّوءِ\nدنیا را مانند بدهکار بد قرار بده!\nحَصَلَ مِنْهُ مَا یَرْضَخُ لَکَ بِهِ\nمقدار کمی را که به تو می‌پردازد بپذیر\n\n◀️ این نگاه رامقایسه کنید با کسانی که میخواهندبه کل دنیا برسند،میخواهند همه ی آن بدیهیشان را از دنیا بگیرند. تازه آرزوهای بلند و بالا هم دارند اینها گرفتارند. ‌\n🔻حضرت فرمودند:اگر چیزی هم دنیا از توگرفته شد ناراحت نباش .\nاین قاعده اگر درذهن انسان باشد درکم وزیاد شدن دنیا خیلی نگران وافسرده نخواهد شد.\nبخش اول :خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ ،\nبخش دوم: وَ تَوَلَّ عَمَّا تَوَلَّى عَنْکَ\n  بخش سوم: فَإِنْ أَنْتَ لَمْ تَفْعَلْ، فَأَجْمِلْ فِی الطَّلَبِ\nو اگر چنین نمى کنى لااقل در طلب دنیا به صورت معقول تلاش کن و تندروى مکن.\nحضرت بعد از بیان دو نقطه ی ایده آل که زهد و تاسف نخوردن بر دنیاست؛\nبرای  کسانی که توان رسیدن به قله را ندارند؛ پیشنهاد دیگری مطرح میکنند و آن نیز “میانه روی در دنیاست”\nجمله ی ” فَإِنْ أَنْتَ لَمْ تَفْعَلْ” دو مصداق دارد:\n1⃣ کسانی که اصرار دارند وضعیت مادی آنها خوب شود، علاقه به ثروت دارند.\n2⃣ کسانی که توان تحمل سختی ها را ندارند، صبر بر مشکلات ندارند.\n✍️هیچ جای شک و شبهه نیست که اتفاقا اکثر افراد جامعه جزء همین دو دسته به حساب می آیند؛ لذا حضرت برای اینکه اینها نیز از مسیر زندگی مومنانه خارج نشوند میفرماید ” میانه روی اقتصادی” داشته باشید.\nاگر اصرار دارى بر مال و جاه خود بیفزایى، تندروى مکن; عاقلانه تلاش کن و آلوده گناهان مشو.\n⏪عقل به تو می‌گوید: پول دربیاور ولی پول مردم را نخور،عقل به تو میگوید پول در بیاور ولی سلامتیت مهمتر از پول است،پول در بیاور ولی خرج کن ذخیره نکن خساست به خرج نده حضرت فرمودند:مسیر اعتدال،مسیر عقل را در کسب وخرج در هر دو پیاده کنید.زاهد نشدید صبور نشدید طوری نیست ولی حداقل موازین شرع را انسان رعایت کند.این میانه روی اقتصادی درمشی نهج البلاغه درمشی اسلام است .\n❇️معنای اجمال در طلب:\nلفظ ” فَأَجْمِلْ فِی الطَّلَبِ” از ماده ی جمال و زیبایی است ولی در حکمت مورد نظر از آنجایی که اعتدال حد وسط افراط و تفریط است و اعتدال همیشه زیباست؛ در معنای حکمت لفظ جمال را به معنای میانه روی ترجمه کردیم.\n❇️عاقل، کارگر دنیا نمیشود:\nحضرت فرمودند: عاقلانه رفتارکنیدحداقلها را رعایت کنید‌یکی از اموری که انسانهای عاقل رعایت می‌کنند برده دنیا نمیشوندبند بردگی به گردن خودشان نمی اندازند.\n\n🔻پیامبر اکرم صَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم میفرمایند:\nپیامبر صلوات الله علیه در حالى که غمگین بود از منزل خارج شد فرشته اى خدمت آن حضرت آمد در حالى که کلید گنج هاى زمین را در دست داشت عرض کرد: اى محمّد! این کلید گنج هاى زمین است پروردگارت مى فرماید: آن ها را بگشا و هرچه مى خواهى بردار بى آن که چیزى از مقام تو نزد من کم شود.\n🔻 فَقَالَ رَسُولُ اللَّهِ(صلى الله علیه وآله) الدُّنْیا دَارُ مَنْ لاَ دَارَ لَهُ وَ لَهَا یجْمَعُ مَنْ لاَ عَقْلَ لَهُ  \nفرمود: دنیا خانه کسى است که خانه دیگرى ندارد و آن را کسى گردآورى مى کند که عقلى ندارد.\n \nانسان عاقل برای دنیا چیزی جمع نمیکند،برای خرج ومخارج خودش برای زندگی دنیا استفاده می‌کند، پول به دست می آورد ولی جمع نمیکند، زیاده روی نمی کند.\n✍️با دنیا باید عاقلانه و با اعتدال برخورد کرد نه اینکه دست انداخت و همه ذخائر دنیا را برای خود برداشت، که این به زیان انسان خواهد بود.\n✳️طلب زیبای رزق، سفارش جبرئیل به پیامبر:\n🔻پیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nألا وإنّ الرُّوحَ الأمینَ نَفَثَ فیرُوعِی أ نّهُ لَن تَمُوتَ نفسٌ حتّى تَستَکمِلَ رِزقَها\nهمانا روح الامین در دلم چنین افکند که هیچ کسی نمیرد تا روزى اش را به طور کامل دریافت کند.\nفاتَّقُوا اللّه و أجمِلُوا فی الطَّلَبِ\nپس، از خدا بترسید و در طلب روزى آرام و معتدل باشید.\n⏪اعتدال ومیانه روی درکسب پول داشته باشید یک حدو حدودی را برای خودتان رعایت کنید،یک اعتدالی یک مرزی را که از دین خارج نشوید را برای خودتان قرار بدهید.نفس انسان سرکش است دنیا طلب است باید افسار نفس راکشید اورایک جایی الزام کردبه دست کشیدن از دنیا.\n✅افسار مرکب دنیا طلبی را باید کشید:\nنامه ۳۱:\nوَ اعْلَمْ یَقِیناً أَنَّکَ لَنْ تَبْلُغَ أَمَلَکَ\nو به یقین بدان هرگز به همه آرزوهایت دست نخواهى یافت\n وَ لَنْ تَعْدُوَ أَجَلَکَ  \nو بیش از آنچه مقرر شده عمر نمى کنى\nوَ أَنَّکَ فِی سَبِیلِ مَنْ کَانَ قَبْلَکَ  \nو تو در همان مسیرى هستى که پیشینیان تو بودند،آنها رفتند و تو هم خواهى رفت\nفَخَفِّضْ فِی الطَّلَبِ وَ أَجْمِلْ فِی الْمُکْتَسَبِ\nحال که چنین است، در به دست آوردن دنیا زیاده روى مکن و در کسب و کار میانه رو باش\n📚این نامه 31 ،نامه ی تربیتی است امیرالمومنین علیه السلام به امام مجتبی علیه السلام میفرمایند:وبه همه ی ما میگویند به بچه هاتون یاد بدهید و خودتان یاد بگیرید اولا رزق ثابت است ثانیا اجل مقدر است، شما نمی توانید به همه ی آرزوها برسید درست زندگی کنید، درست کسب وکار کنید ،دزدی نکنید، برای رسیدن به دنیا چیزی که حق نیست را نگیر.پس قشنگ زندگی کنید،زندگی زیبا می‌تواند آینده تورا ،بهشت تو را تضمین کند.\n✳️ تنها راه آرامش در زندگی اجتماعی و شخصی، عمل به ” فَأَجْمِلْ فِی الطَّلَبِ” است:\nمشکلات عظیمى که در دنیاى دیروز و امروز و فردا وجود داشته، دارد و خواهد داشت؛ ناشى از حرص حریصان و دنیاپرستان است که به سهم و حق خود از دنیا قانع نیستند و اصرار دارند از دیگران بگیرند و به خود بیفزایند.\nسرچشمه جنگ ها و نزاع ها و بسیارى از پرونده هاى سنگین دادگاه ها همین حرص دنیا و بیش از حق خود طلبیدن است.\nاگر به دستورى که حضرت عمل شود آتش جنگ ها خاموش مى گردد و پرونده هاى دادگاه ها بسته خواهد شد\n🔹شاعر عرب پایان مى گوید:\nیا حَرِیصاً قَطَع الأیّامَ فِى * بُؤسِ عَیْش وَعَناء و تَعَب\nاى کسى که تمام روزها را در ناراحتى و رنج و تعب براى افزودن مال و ثروت، مى گذرانى!\nلَیْسَ یَعدُوکَ مِنَ الرِّزقِ الّذِى * قَسَم اللّهُ، فأجْمِل فى الطَّلَب\nبدان آن رزقى که خدا براى تو مقرر کرده است از تو دریغ نخواهد شد بنابراین در طلب دنیا معقولانه رفتار کن\n✍️به اندازه ای که نیاز دارید تلاش کنید نه به اندازه آرزوی که درسرمیپرورانید .\n✳️دنیا طلب ها را در یک مورد اسوه بگیرید:\n📚شیخ صدوق در امالی روایت نقل میکند: المسیحُ علیه السلام : یا بَنِی إسرائیلَ ، لا تَأسَوا على ما فاتَکُم مِن دُنیاکُم إذا سَلِمَ دِینُکُم\nاى بنى اسرائیل! هر گاه دینتان سالم بود ، براى از دست دادن دنیاتان افسوس نخورید\nکما لا یَأسى أهلُ الدنیا على ما فاتَهُم مِن دِینِهِم إذا سَلِمَتْ دُنیاهُم\nهمچنان که دنیا پرستان هر گاه دنیایشان سالم باشد ، براى از دست دادن دینشان اندوهى به خود راه نمى دهند.\n✍️ ما حداقل به اندازه ی دنیا طلب ها متعصب باشیم.\n آنها وقتی دنیایشان رو به راه باشد برای دین دل نمیسوزانند، ما هم وقتی دینمان درست و سالم بود برای دنیا دل نسوزانیم و به حد کفاف آن قانع باشیم.\n🔻”اَلْإِجْمَالَ فِی اَلطَّلَبِ”، از اصطلاحات پر کاربرد روایات:\n✅اجمال فی الطلب عفت است:\nامام مجتبی علیه السلام: لاَ تُجَاهِدِ اَلطَّلَبَ جِهَادَ اَلْغَالِبِ\nنه چون پیروزمندان در طلب دنیا بکوش کسانی که مزه دنیا زیر دندانشان رفته و در طلب کسب بیشتر اند.\nوَ لاَ تَتَّکِلْ عَلَی‌ اَلْقَدَرِ اِتِّکَالَ اَلْمُسْتَسْلِمِ\nنه مانند تسلیم‌شدگان به تقدیر تکیه کن و بیماری را پیشه نکن .\nفَإِنَّ اِبْتِغَاءَ اَلْفَضْلِ مِنَ اَلسُّنَّهِ\nکه رفتن دنبال فضل و احسان خدا  سنت و قانون هستی است.\nوَ اَلْإِجْمَالَ فِی اَلطَّلَبِ مِنَ اَلْعِفَّهِ  \nاعتدال در طلب روزی نشانه ی عفت است.\n✳️خودنگهداری در برابر تمایلات:\nعفت خیلی مقام بزرگی است عفت بسیار جایگاه رفیعی است اگر کسی می‌خواهد به عفت برسد یکی از راه‌ها این است عفت درمقابل مالی یعنی به حداقل‌ها اکتفا کنید همینکه زیاده روی نکنید، کافیه پول دارید دنبال پول هم هستید ،حضرت فرمودند طوری نیست اجمال داشته باشید خطوط قرمز را ردنکنید این یک مدل از عفاف اقتصادی است.\n❇️اجمال فی الطلب نشانه ی ایمان است:\nامیرالمومنین علیه السلام:\n سِتَّهٌ تُخْتَبَرُ بِهَا دِینُ اَلرَّجُلِ: اَلْوَرَعُ، وَ اَلتَّقْوَی‌، وَ صِدْقُ اَلْیَقِینِ، وَ مُجَاهَدَهُ اَلْهَوَی‌، وَ اَلْعِفَّهُ، وَ اَلْإِجْمَالُ فِی اَلطَّلَبِ . دین مردم را آزمود: ورع ،تقوا، یقین صادقانه، مبارزه با نفس، عفت، و میانه روی در خواستن.\nیکی از مواردی که انسان می‌تواند دین خود را بسنجدآن است که شما چقدر اجمال فی الطلب دارید؟چقدر میانه روی دارید؟چقدر از حرص دور هستید؟هرچه کمتر باشد دینداری شما بزرگتر وغنی تر است.باید با پنبه سردنیا رابرید با یداز دنیا بهره برداری کنیم نه با سروصدا نه باحرص نه طوری که اومارا به بندگی بکشد.\n✳️باید با پنبه سر دنیا را برید و بهره را از او گرفت:\nامیرالمومنین علیه السلام :\nاَلدُّنْیَا دُوَلٌ فَاطْلُبْ حَظَّکَ مِنْهَا بِإِجْمَالِ اَلطَّلَبِ\nدنیا دست بدست میچرخد تو بهره خود را از آن با آرامی‌ جستجو کن و حریص مباش.\n✍️ کسانی که میخواهند هیجانی و بیش از حد از دنیا بهره ببرند، دنیا متوجه میشود و با آنها گلاویز میشود. ولی کسانی که آهسته به سراغ دنیا میروند، میتوانند همه بهره شان را بی درد سر از دنیا بگیرند.\n✳️اجمال فی الطلب در سیره امیرالمومنین:\nدرنامه ۴۵ به عثمان بن حنیب:\nوَ لَوْ شِئْتُ لاَهْتَدَیْتُ اَلطَّرِیقَ إِلَى مُصَفَّى هَذَا اَلْعَسَلِ وَ لُبَابِ هَذَا اَلْقَمْحِ وَ نَسَائِجِ هَذَا اَلْقَزِّ  \nفکر نکنید من قادر به تحصیل لذت هاى دنیا نیستم. به خدا سوگند اگر مى خواستم مى توانستم از عسل مصفا و مغز گندم و بافته هاى ابریشم براى خود بهترین غذا و لباس را تهیّه کنم\nوَ لَکِنْ هَیْهَاتَ أَنْ یَغْلِبَنِی هَوَایَ وَ یَقُودَنِی جَشَعِی إِلَى تَخَیُّرِ اَلْأَطْعِمَهِ\nاما هیهات که هواى نفس بر من چیره شود و حرص و طمع مرا وادار به انتخاب طعام هاى لذیذ نماید.\n✍️ حضرت میتوانست بهترین ها را داشته باشد، آن هم از راه حلال و درست ولی اراده کرد میانه روی و زهد در مسیر دنیا را در پیش بگیرد.\n✅نکته:\nباید در به دست آوردن دنیا، زیبایی را لحاظ کرد:\nاگر چه در ابتدای بحث بیان شد که در این حکمت اجمال را به معنای اعتدال میگیریم؛ ولی نباید غافل بود که از جهت لغوی این لفظ به معنای زیبایی است؛ پس باید در طلب دنیا، دنیا طلب زیبا بود.\nکسب زیبا به معنای تلاش برای به دست آوردن روزی از راه‌های حلال، معقول، و با حفظ کرامت انسانی است.\nاین نوع کسب، تنها برای انباشت ثروت نیست، بلکه برای تأمین نیازهای مشروع خود و خانواده، استقلال اقتصادی و قوت گرفتن برای عبادت خداوند است.\n✳️مال حلال، زیبا است:\nکسب وکار و در آمدتان و رزق و روزیتان زیبا باشد. از جایی پول به دست آورید که زیبا باشد. طوری خرج کنید که زیبا باشد.هرکاری که باعث زشتی میشود از خودتان دور کنید.هرمدل پول به دست آوردن که زشت است از تو باید دور باشد. محرمات، مکاسب محرمه زشت است ربا، قمار،زشت است دنبالشان نروید.هرچیزی که زشت باشد دراین دایره جایی ندارد.حضرت فرمودند کار کنیدوظیفه تان است ولی پول قشنگ به دست بیارید.\nقرآن کریم میفرماید:\nیَا أَیُّهَا النَّاسُ کُلُوا مِمَّا فِی الْأَرْضِ حَلَالًا طَیِّبًا\nای مردم! از آنچه در زمین است حلال و پاکیزه بخورید.\n❇️تجارت، بعد از انجام تکالیف عبادی زیباست:\nقرآن کریم در سوره جمعه میفرماید: فَإِذَا قُضِیَتِ الصَّلَاهُ فَانْتَشِرُوا فِی الْأَرْضِ وَابْتَغُوا مِنْ فَضْلِ اللَّهِ\nپس هنگامی که نماز اتمام یافت، در زمین پراکنده شوید و از فضل خدا روزی بجویید.\n⏪پول زیبا پولی است که شما وظیفه ی شرعیتان را انجام بدهیدحالا دنبال کاربردی کاریه انجام می‌دهید پولش زیباست پولش تربیت فرزند شما را به درستی انجام میدهد.\n✍️ این آیه الگویی زیبا ارائه می‌دهد.\nاولویت با عبادت است و سپس تلاش برای روزی در چارچوب رضایت خدا.\n✅کسب در آمدی که با یاد خدا باشد زیباست:\nقرآن کریم در سوره نور میفرماید: رِجَالٌ لَّا تُلْهِیهِمْ تِجَارَهٌ وَلَا بَیْعٌ عَن ذِکْرِ اللَّهِ  \nمردانی که هیچ تجارت و خرید و فروشی آنان را از یاد خدا غافل نمی‌کند…\n◀️کاری که همراه باذکرباشد.پول به دست آوردن که همره با توجه به خدا باشد میشود پول به دست آوردن زیبا\n✍️ نمیفرماید آنها اهل کار نیستند، میفرماید کار آنها را از ذکر و یاد خدا غافل نمیکند.\n✳️رزقی که از طریق جوانمردان برسد زیباست:\nباجوانمردها معاشرت کنید.باجوانمردها دادو ستد کنید.\nحکمت ۶۶:\nفَوْتُ الْحَاجَهِ، أَهْوَنُ مِنْ طَلَبِهَا إِلَى غَیْرِ أَهْلِهَا\nاز دست رفتن حاجت بهتر از طلب کردن آن از نااهلان است!\n⏪اگر می‌خواهید پول زیبا داشته باشید قرضم که خواستید بگیرید از یک انسان جوانمرد بگیرید ولی اگر حق خودتان را از ناجوانمرد گرفتید این به آن زیبایی که باید باشد نیست.\n✅رزقی که دسترنج باشد، زیباست:\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nأطیَبُ الکَسبِ عَمَلُ الرجُلِ بیَدِهِ\nپاکترین کسب و درآمد، دسترنج آدمى است.\n🔺در روایت آمده است: از معجزه زیباتر، کار کردن است:\n📚مرحوم مجلسی در بحار نقل میکند:\nرُویَ أنَّ حَوارِیِّی عیسى علیه السلام کانوا إذا جاعُوا قالوا : یا رُوحَ اللّه جُعْنا ، فَیَضرِبُ بیَدِهِ علَى الأرضِ ـ\nروایت شده است که حواریان عیسى علیه السلام هر گاه گرسنه مى شدند، مى گفتند: یا روح اللّه ! گرسنه شده ایم. پس، عیسى علیه السلام با دست خود به زمین، چه دشت بود و چه کوه، مى زد و براى هر یک از حواریان دو گرده نان بیرون مى آورد، که آنها را مى خوردند.\nفإذا عَطِشُوا قالوا : یا رُوحَ اللّه عَطِشْنا ، فَیَضرِبُ بیَدِهِ على الأرضِ ـ سَهلاً کان أو جَبَلاً ـ فَیُخرِجُ ماءً فَیَشرَبُونَ  \nو هر گاه تشنه مى شدند، مى گفتند: یا روح اللّه ! تشنه شده ایم و آن حضرت با دستش به زمین، خواه دشت بود یا کوه، مى زد و آب بیرون مى آورد و حواریان مى نوشیدند..\nقالوا : یا رُوحَ اللّه ، مَن أفضَلُ مِنّا ؟ إذا شِئنا أطعَمتَنا ، و إذا شِئنا سَقَیتَنا ، و قد آمَنّا بکَ و اتَّبَعناکَ !\nآنها گفتند: یا روح اللّه ! چه کسى از ما برتر است که هر گاه مى خواهیم غذایمان مى دهى و هر گاه مى خواهیم آبمان مى نوشانى در حالى که همه ما به تو ایمان آورده ایم و پیرویت مى کنیم؟\n قالَ : أفضَلُ مِنکُم مَن یَعَملُ بیَدِهِ ، و یَأکُلُ مِن کَسبِهِ  \nعیسى علیه السلام فرمود: برتر از شما، کسى است که با دست خود کار کند و از کسب خودش بخورد.\nفصاروا یَغسِلُونَ الثِّیابَ بالکِراءِ\nاز آن پس حواریان رخت مى شستند و اجرت مى گرفتند.\n✍️پولی که از دسترنج انسان باشد زیباست ولی پولی که باد آورده باشدزیبایی ندارد.\n✳️ رزقی که انسان برای آن  جانش را به خطر نیندازد زیباست:\nمصداقش را درروایات داریم\nامیرالمومنین علیه السلام:\nمَا أَجْمَلَ فِی اَلطَّلَبِ مَنْ رَکِبَ اَلْبَحْرَ لِلتِّجَارَهِ.\nکسی که برای تجارت از راه دریا اقدام کند، در کسب روزی اعتدال به خرج نداده است\n✍️ در گذشته سفرهای دریایی سخت و خطرناک بود، ماهها می رفتند و زن و فرزند، در انتظار و دلهره بودند. حضرت می فرماید این سفرها برای کسب در آمد مناسب نیست.\n❇️رزقی که در وطن به دست بیاید زیباست:\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nأربَعهٌ مِن سَعادَهِ المَرءِ .\nچهار چیز از خوشبختى مرد است\nالخُلَطاءُ الصّالِحُونَ\nهمنشینان شایسته\nو الوَلَدُ البارُّ\nفرزند نیکوکار،\nو المَرأهُ المُؤاتِیَهُ\nزن سازگار،\nو أن تَکونَ مَعِیشَتُهُ فی بَلَدِهِ\nو این که محل کسب او در شهر خودش باشد.\n\n✍️ رزق اگر به دست بیاید ولی آبروی انسان را در معرض خطر قرار دهد، زیبا نیست.\n \n✅کسب  در آمد از طریق ریاست طلبی زیبا نیست:!\nامام صادق علیه السلام:\nمَلْعُونٌ مَنْ تَرَأَّسَ\nملعون است کسى‌که ریاست به خود بندد\nمَلْعُونٌ مَنْ هَمَّ بِهَا   \nملعون است کسى‌که دنبال رسیدن به ریاست باشد\nمَلْعُونٌ مَنْ حَدَّثَ بِهَا نَفْسَهُ\nملعون است کسى که به فکر آن باشد.\nدارد درس می‌خواند تا فردا به پست و‌مقامی برسد.پست ومقام و مسئولیت وظیفه است نباید دنبال آن برود پولی هم که از این راه به دست می آورد زیبا نیست.\n🔹 وقتی امیرالمومنین علیه السلام فرزندان عمویش عباس را مسئولیت داد، مالک اشتر اعتراض کرد که اگر قصه فامیل بازی است، چرا ما عثمان را کشتیم.\n🔹حضرت با ملاطفت به مالک فرمود من که فرزندان خودم را به مسئولیت نگمارده ام و علت اینکه به فرزندان عباس مسئولیت دادم این است که اولا افراد شایسته ای هستند، ثانیا در دوران خلفا به آنها ظلم شد، چون فامیل ما بودند، ثالثا اگر کسی بهتر میشناسی بیاور تا جابجا کنم.\nامیرالمومنین علیه‌السلام فرمود:\nاِنِّی سَمِعْتُ اَلْعَبَّاسَ یَطْلُبُ مِنْ رَسُولِ اَللَّهِ صَلَّى اَللَّهُ عَلَیْهِ وَ آلِهِ اَلْإِمَارَهَ مِرَاراً  \nمن مکرر از عمویم عباس شنیدم که از پیامبر طلب مسئولیت میکرد.\nفَقَالَ لَهُ رَسُولُ اَللَّهِ صَلَّى اَللَّهُ عَلَیْهِ وَ آلِهِ یَا عَمِّ إِنَّ اَلْإِمَارَهَ إِنْ طَلَبْتَهَا وُکِّلْتَ إِلَیْهَا وَ إِنْ طَلَبَتْکَ أُعِنْتَ عَلَیْهَا\nپیامبر صلوات الله علیه و آله فرمود ای عمو حکومت را اگر طلب کنی به همان حکومت واگذار میشوی و اگر او تو را طلب کند خداوند در آن کار به تو یاری می‌رساند.\n✍️باید برای به دست آوردن رزق زیبا منتظر بود تا با توجه به تخصص فرد به او پیشنهاد پست و مقامی پیشنهاد بشود، وگرنه کسی که مدام دنبال رسیدن به جایگاه بالایی است آن پولی که بدست می آورد پول زیبایی نیست.\n\nغفر الله لی و لکم، الحمدلله رب العالمین\n💠وَ قَالَ (علیه السلام): خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ\nاز دنیا همان قدر را بگیر که به سراغ تو مى آید.\n💠 وَ تَوَلَّ عَمَّا تَوَلَّى عَنْکَ\nو از آنچه از تو روى گردانده روى بگردان و به دنبال آن مشتاب،\n💠فَإِنْ أَنْتَ لَمْ تَفْعَلْ، فَأَجْمِلْ فِی الطَّلَبِ\nو اگر چنین نمى کنى لااقل در طلب دنیا به صورت معقول تلاش کن و تندروى مکن.\n🔻امیرالمومنین علیه السلام در این حکمت در مورد بهره گرفتن از دنیا سه دستور میدهند:\n1⃣ اگر میتوانید با دنیا زاهدانه برخورد کنید.\n2⃣ اگر میتوانید برای از دست رفتن دنیا، صبر به خرج بده.\n3⃣ اگر نمیتوانید زاهد و صبور باشید، لااقل با دنیا به زیبایی مواجه شو و میانه روی کنید.\n💠دربخش اول حکمت آمده :\nخُذْ مِنَ الدُّنْیَا مَا أَتَاکَ\nاز دنیا همان قدر را بگیر که به سراغ تو مى آید.\nامیرالمومنین علیه السلام درباب رزق و روزی مطالب فراوانی دارند.\nاساس مطالب درمورد رزق وروزی حکمت ۴۳۱:\nالرِّزْقُ رِزْقَانِ، طَالِبٌ وَ مَطْلُوبٌ\nروزى بر دو گونه است: یکى آن‏که به ‏دنبال انسان مى ‏آید و دیگر آن‏که انسان به‏ دنبال آن مى‏ رود.\nرزق طالب هم روزی های نانوشته ای است که خداوند برای انسان مقدر کرده است،\nهم رزق و روزی است که هر انسانى در شرایط معمولى با کسب و کار عادى و آبرومند به دست می آورد.\nزیاده روی بداست ،حرص ،جمع کردن،بخل بداست.وگرنه استفاده به اندازه رزق طالب و رزق مطلوب بسیار خوب است.کسب وکار باید آبرومند باشد،انسان تلاش کندو کارکندپول به دست بیاورد،برای رفاه خودش وخانواده اش خرج کند.\n✍️حقیقت زهد نیز همین بود که انسان حرص و طمع به دنیا نداشته باشد، وابسته ی به دست آوردن حجم بیشتری از کالای دنیا نباشد.\nلذا حضرت در توصیه ی اول به اصل زهد، قناعت و کفاف امر میکنند.\nپر واضح است که هرگز منظور امام  از  ” خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ ” این نیست که انسان در خانه خود بنشیند تا رزق و روزى اش به سراغ او بیاید این همان چیزى است که با صراحت در روایات از آن نهى شده است.  و ما مامور به کار هستیم.\n⏪منظور آن است که اصرار بر افزودن مال و ثروت در جایى که اسبابش فراهم نیست نداشته باشد چراکه:\nزیاده روی ها حداقل سه آفت ومشکل برای شما ایجاد میکند:\n1⃣هم مشقت زیادى را بر انسان تحمیل مى کند.\nدرروایت داریم که خداوند به دنیا وحی کرد که اگر کسی دنبال توبود از دست آن فرار کن اورابه بردگی بکش بارروی دوش اوبگذار.\n2⃣ ممکن است آلوده انواع گناهان و انحراف از مسیر شرع شود.\nکسی که همه ی همتش شد پول درآوردن برای به دست آوردن پول حاضر است،هرکاری بکند حتی دین فروشی.\n3⃣ اگر به آن نرسد زبان به ناشکرى و کفران بگشاید.\nاگر انسان اعتدال را رعایت کرد دیگر به این آفت‌ها دچار نخواهد شد.\n✳️خیالمان از روزی راحت باشد:\n🔻در حکمت ۳۶۵ از حضرت سوال شد:\nلَوْ سُدَّ عَلَى رَجُلٍ بَابُ بَیْتِهِ وَ تُرِکَ فِیهِ، مِنْ أَیْنَ کَانَ یَأْتِیهِ رِزْقُهُ؟ فَقَالَ (علیه السلام): مِنْ حَیْثُ یَأْتِیهِ أَجَلُه.\nاز امام علیه السلام پرسیدند: اگر درِ خانه کسى را به روى او ببندند و در همان جا محبوس گردد از کجا روزى اش مى رسد؟ امام علیه السلام در پاسخ فرمود: از همان جا که اجل به سراغ او مى آید!\n💠خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ\nآنچه که از دنیا به سمت تو میآیدآن رابگیر\n💠وَ تَوَلَّ عَمَّا تَوَلَّى عَنْکَ\nو از آنچه از تو روى گردانده روى بگردان و به دنبال آن مشتاب.\n◀️در مسیر زندگی، خیلی اوقات انسان برای رسیدن به اهداف و خواسته هایش تلاش میکند ولی به هر دلیلی به خواسته هایش نمیرسد؛ یا به خواسته هایش میرسد ولی بعد از مدتی آنها را از دست میدهد.\n↩️یا پست است مقام، پول،یاکلا نمیرسد یا اگر رسید دنیا دولت است دست به دست میشود،از این نفربه نفربعدی منتقل می‌کند.مواجه ما با این عادت دنیا چه باشد؟دنیا کارش این است که ازکسی بگیرد و به دیگری بدهد.جنس،مال،قدرت در دست هیچ کسی ثابت نیست.اگرذات دنیا این است اینجا دو راه دارد:\n1⃣ یا نشستن و گریستن بر آنچه از دست رفته، و حسرت آنها را خوردن و افسردگی بعد از شکست.\n2⃣یا دل از آنها بریدن، چشم از آنها برداشتن و ادامه دادن مسیر به سمت اهداف جدید؛ با تجربه ای بیشتر.\n✍️ به فرایندِ گیر نکردن پشت دست انداز مشکلات؛ صبر میگویند.\nوقتی سدی ایجاد میشود چیزی را از تو میگیرند،این توقف نکردن می‌شود صبر. اگر دائم گریه وزاری کردید این صبر نیست،اگر گذشتید حالت صبر است.\n❇️هر چه از تو روی گرداند، از آن روی بگردان:\nقرآن کریم میفرماید:\nلِکَیْلَا تَأْسَوْا عَلَىٰ مَا فَاتَکُمْ وَ لَا تَفْرَحُوا بِمَا آتَاکُمْ.\nبر آنچه از دست شما رفت، تأسف نخورید، و بر آنچه به شما عطا کرده است، شادمان و دلخوش نشوید.\n⏪اگرچیزی دادندالحمدالله نعمتی است که درپس آن وظیفه است اگرچیزی گرفتند الحمدالله نعمت داده بودندو گرفتند مسیرطبیعی دنیا همین است .میدهند و میگیرند پس افسوس خوردن و حسرت خوردن ندارد.\n✍️ دل بریدن از آنچه از دست انسان رفته است و صبر بر آن دومین توصیه حضرت است.\n🔻در نامه ۴۷ که وصیت نامه هنگام شهادت حضرت است فرمود:\nأُوصِیکُمَا بِتَقْوَى اللَّهِ، وَ أَلَّا تَبْغِیَا الدُّنْیَا وَ إِنْ بَغَتْکُمَا\nمن شما را به تقوا و پرهیزکارى توصیه مى کنم و سفارش مى کنم و در پى زرق و برق دنیا نباشید، هرچند دنیا به سراغ شما بیاید\nوَ لَا تَأْسَفَا عَلَى شَیْءٍ مِنْهَا زُوِیَ عَنْکُمَا\nو بر آنچه از دنیا از دست مى دهید تأسف نخورید.\n✳️دنیا مثل بدهکار فراری است:\nمثال ابن ابی الحدید:\nاجْعَلِ الدُّنْیَا کَغَرِیمِ السُّوءِ\nدنیا را مانند بدهکار بد قرار بده!\nحَصَلَ مِنْهُ مَا یَرْضَخُ لَکَ بِهِ\nمقدار کمی را که به تو می‌پردازد بپذیر\n\n◀️ این نگاه رامقایسه کنید با کسانی که میخواهندبه کل دنیا برسند،میخواهند همه ی آن بدیهیشان را از دنیا بگیرند. تازه آرزوهای بلند و بالا هم دارند اینها گرفتارند. ‌\n🔻حضرت فرمودند:اگر چیزی هم دنیا از توگرفته شد ناراحت نباش .\nاین قاعده اگر درذهن انسان باشد درکم وزیاد شدن دنیا خیلی نگران وافسرده نخواهد شد.\nبخش اول :خُذْ مِنَ الدُّنْیَا مَا أَتَاکَ ،\nبخش دوم: وَ تَوَلَّ عَمَّا تَوَلَّى عَنْکَ\n  بخش سوم: فَإِنْ أَنْتَ لَمْ تَفْعَلْ، فَأَجْمِلْ فِی الطَّلَبِ\nو اگر چنین نمى کنى لااقل در طلب دنیا به صورت معقول تلاش کن و تندروى مکن.\nحضرت بعد از بیان دو نقطه ی ایده آل که زهد و تاسف نخوردن بر دنیاست؛\nبرای  کسانی که توان رسیدن به قله را ندارند؛ پیشنهاد دیگری مطرح میکنند و آن نیز “میانه روی در دنیاست”\nجمله ی ” فَإِنْ أَنْتَ لَمْ تَفْعَلْ” دو مصداق دارد:\n1⃣ کسانی که اصرار دارند وضعیت مادی آنها خوب شود، علاقه به ثروت دارند.\n2⃣ کسانی که توان تحمل سختی ها را ندارند، صبر بر مشکلات ندارند.\n✍️هیچ جای شک و شبهه نیست که اتفاقا اکثر افراد جامعه جزء همین دو دسته به حساب می آیند؛ لذا حضرت برای اینکه اینها نیز از مسیر زندگی مومنانه خارج نشوند میفرماید ” میانه روی اقتصادی” داشته باشید.\nاگر اصرار دارى بر مال و جاه خود بیفزایى، تندروى مکن; عاقلانه تلاش کن و آلوده گناهان مشو.\n⏪عقل به تو می‌گوید: پول دربیاور ولی پول مردم را نخور،عقل به تو میگوید پول در بیاور ولی سلامتیت مهمتر از پول است،پول در بیاور ولی خرج کن ذخیره نکن خساست به خرج نده حضرت فرمودند:مسیر اعتدال،مسیر عقل را در کسب وخرج در هر دو پیاده کنید.زاهد نشدید صبور نشدید طوری نیست ولی حداقل موازین شرع را انسان رعایت کند.این میانه روی اقتصادی درمشی نهج البلاغه درمشی اسلام است .\n❇️معنای اجمال در طلب:\nلفظ ” فَأَجْمِلْ فِی الطَّلَبِ” از ماده ی جمال و زیبایی است ولی در حکمت مورد نظر از آنجایی که اعتدال حد وسط افراط و تفریط است و اعتدال همیشه زیباست؛ در معنای حکمت لفظ جمال را به معنای میانه روی ترجمه کردیم.\n❇️عاقل، کارگر دنیا نمیشود:\nحضرت فرمودند: عاقلانه رفتارکنیدحداقلها را رعایت کنید‌یکی از اموری که انسانهای عاقل رعایت می‌کنند برده دنیا نمیشوندبند بردگی به گردن خودشان نمی اندازند.\n\n🔻پیامبر اکرم صَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم میفرمایند:\nپیامبر صلوات الله علیه در حالى که غمگین بود از منزل خارج شد فرشته اى خدمت آن حضرت آمد در حالى که کلید گنج هاى زمین را در دست داشت عرض کرد: اى محمّد! این کلید گنج هاى زمین است پروردگارت مى فرماید: آن ها را بگشا و هرچه مى خواهى بردار بى آن که چیزى از مقام تو نزد من کم شود.\n🔻 فَقَالَ رَسُولُ اللَّهِ(صلى الله علیه وآله) الدُّنْیا دَارُ مَنْ لاَ دَارَ لَهُ وَ لَهَا یجْمَعُ مَنْ لاَ عَقْلَ لَهُ  \nفرمود: دنیا خانه کسى است که خانه دیگرى ندارد و آن را کسى گردآورى مى کند که عقلى ندارد.\n \nانسان عاقل برای دنیا چیزی جمع نمیکند،برای خرج ومخارج خودش برای زندگی دنیا استفاده می‌کند، پول به دست می آورد ولی جمع نمیکند، زیاده روی نمی کند.\n✍️با دنیا باید عاقلانه و با اعتدال برخورد کرد نه اینکه دست انداخت و همه ذخائر دنیا را برای خود برداشت، که این به زیان انسان خواهد بود.\n✳️طلب زیبای رزق، سفارش جبرئیل به پیامبر:\n🔻پیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nألا وإنّ الرُّوحَ الأمینَ نَفَثَ فیرُوعِی أ نّهُ لَن تَمُوتَ نفسٌ حتّى تَستَکمِلَ رِزقَها\nهمانا روح الامین در دلم چنین افکند که هیچ کسی نمیرد تا روزى اش را به طور کامل دریافت کند.\nفاتَّقُوا اللّه و أجمِلُوا فی الطَّلَبِ\nپس، از خدا بترسید و در طلب روزى آرام و معتدل باشید.\n⏪اعتدال ومیانه روی درکسب پول داشته باشید یک حدو حدودی را برای خودتان رعایت کنید،یک اعتدالی یک مرزی را که از دین خارج نشوید را برای خودتان قرار بدهید.نفس انسان سرکش است دنیا طلب است باید افسار نفس راکشید اورایک جایی الزام کردبه دست کشیدن از دنیا.\n✅افسار مرکب دنیا طلبی را باید کشید:\nنامه ۳۱:\nوَ اعْلَمْ یَقِیناً أَنَّکَ لَنْ تَبْلُغَ أَمَلَکَ\nو به یقین بدان هرگز به همه آرزوهایت دست نخواهى یافت\n وَ لَنْ تَعْدُوَ أَجَلَکَ  \nو بیش از آنچه مقرر شده عمر نمى کنى\nوَ أَنَّکَ فِی سَبِیلِ مَنْ کَانَ قَبْلَکَ  \nو تو در همان مسیرى هستى که پیشینیان تو بودند،آنها رفتند و تو هم خواهى رفت\nفَخَفِّضْ فِی الطَّلَبِ وَ أَجْمِلْ فِی الْمُکْتَسَبِ\nحال که چنین است، در به دست آوردن دنیا زیاده روى مکن و در کسب و کار میانه رو باش\n📚این نامه 31 ،نامه ی تربیتی است امیرالمومنین علیه السلام به امام مجتبی علیه السلام میفرمایند:وبه همه ی ما میگویند به بچه هاتون یاد بدهید و خودتان یاد بگیرید اولا رزق ثابت است ثانیا اجل مقدر است، شما نمی توانید به همه ی آرزوها برسید درست زندگی کنید، درست کسب وکار کنید ،دزدی نکنید، برای رسیدن به دنیا چیزی که حق نیست را نگیر.پس قشنگ زندگی کنید،زندگی زیبا می‌تواند آینده تورا ،بهشت تو را تضمین کند.\n✳️ تنها راه آرامش در زندگی اجتماعی و شخصی، عمل به ” فَأَجْمِلْ فِی الطَّلَبِ” است:\nمشکلات عظیمى که در دنیاى دیروز و امروز و فردا وجود داشته، دارد و خواهد داشت؛ ناشى از حرص حریصان و دنیاپرستان است که به سهم و حق خود از دنیا قانع نیستند و اصرار دارند از دیگران بگیرند و به خود بیفزایند.\nسرچشمه جنگ ها و نزاع ها و بسیارى از پرونده هاى سنگین دادگاه ها همین حرص دنیا و بیش از حق خود طلبیدن است.\nاگر به دستورى که حضرت عمل شود آتش جنگ ها خاموش مى گردد و پرونده هاى دادگاه ها بسته خواهد شد\n🔹شاعر عرب پایان مى گوید:\nیا حَرِیصاً قَطَع الأیّامَ فِى * بُؤسِ عَیْش وَعَناء و تَعَب\nاى کسى که تمام روزها را در ناراحتى و رنج و تعب براى افزودن مال و ثروت، مى گذرانى!\nلَیْسَ یَعدُوکَ مِنَ الرِّزقِ الّذِى * قَسَم اللّهُ، فأجْمِل فى الطَّلَب\nبدان آن رزقى که خدا براى تو مقرر کرده است از تو دریغ نخواهد شد بنابراین در طلب دنیا معقولانه رفتار کن\n✍️به اندازه ای که نیاز دارید تلاش کنید نه به اندازه آرزوی که درسرمیپرورانید .\n✳️دنیا طلب ها را در یک مورد اسوه بگیرید:\n📚شیخ صدوق در امالی روایت نقل میکند: المسیحُ علیه السلام : یا بَنِی إسرائیلَ ، لا تَأسَوا على ما فاتَکُم مِن دُنیاکُم إذا سَلِمَ دِینُکُم\nاى بنى اسرائیل! هر گاه دینتان سالم بود ، براى از دست دادن دنیاتان افسوس نخورید\nکما لا یَأسى أهلُ الدنیا على ما فاتَهُم مِن دِینِهِم إذا سَلِمَتْ دُنیاهُم\nهمچنان که دنیا پرستان هر گاه دنیایشان سالم باشد ، براى از دست دادن دینشان اندوهى به خود راه نمى دهند.\n✍️ ما حداقل به اندازه ی دنیا طلب ها متعصب باشیم.\n آنها وقتی دنیایشان رو به راه باشد برای دین دل نمیسوزانند، ما هم وقتی دینمان درست و سالم بود برای دنیا دل نسوزانیم و به حد کفاف آن قانع باشیم.\n🔻”اَلْإِجْمَالَ فِی اَلطَّلَبِ”، از اصطلاحات پر کاربرد روایات:\n✅اجمال فی الطلب عفت است:\nامام مجتبی علیه السلام: لاَ تُجَاهِدِ اَلطَّلَبَ جِهَادَ اَلْغَالِبِ\nنه چون پیروزمندان در طلب دنیا بکوش کسانی که مزه دنیا زیر دندانشان رفته و در طلب کسب بیشتر اند.\nوَ لاَ تَتَّکِلْ عَلَی‌ اَلْقَدَرِ اِتِّکَالَ اَلْمُسْتَسْلِمِ\nنه مانند تسلیم‌شدگان به تقدیر تکیه کن و بیماری را پیشه نکن .\nفَإِنَّ اِبْتِغَاءَ اَلْفَضْلِ مِنَ اَلسُّنَّهِ\nکه رفتن دنبال فضل و احسان خدا  سنت و قانون هستی است.\nوَ اَلْإِجْمَالَ فِی اَلطَّلَبِ مِنَ اَلْعِفَّهِ  \nاعتدال در طلب روزی نشانه ی عفت است.\n✳️خودنگهداری در برابر تمایلات:\nعفت خیلی مقام بزرگی است عفت بسیار جایگاه رفیعی است اگر کسی می‌خواهد به عفت برسد یکی از راه‌ها این است عفت درمقابل مالی یعنی به حداقل‌ها اکتفا کنید همینکه زیاده روی نکنید، کافیه پول دارید دنبال پول هم هستید ،حضرت فرمودند طوری نیست اجمال داشته باشید خطوط قرمز را ردنکنید این یک مدل از عفاف اقتصادی است.\n❇️اجمال فی الطلب نشانه ی ایمان است:\nامیرالمومنین علیه السلام:\n سِتَّهٌ تُخْتَبَرُ بِهَا دِینُ اَلرَّجُلِ: اَلْوَرَعُ، وَ اَلتَّقْوَی‌، وَ صِدْقُ اَلْیَقِینِ، وَ مُجَاهَدَهُ اَلْهَوَی‌، وَ اَلْعِفَّهُ، وَ اَلْإِجْمَالُ فِی اَلطَّلَبِ . دین مردم را آزمود: ورع ،تقوا، یقین صادقانه، مبارزه با نفس، عفت، و میانه روی در خواستن.\nیکی از مواردی که انسان می‌تواند دین خود را بسنجدآن است که شما چقدر اجمال فی الطلب دارید؟چقدر میانه روی دارید؟چقدر از حرص دور هستید؟هرچه کمتر باشد دینداری شما بزرگتر وغنی تر است.باید با پنبه سردنیا رابرید با یداز دنیا بهره برداری کنیم نه با سروصدا نه باحرص نه طوری که اومارا به بندگی بکشد.\n✳️باید با پنبه سر دنیا را برید و بهره را از او گرفت:\nامیرالمومنین علیه السلام :\nاَلدُّنْیَا دُوَلٌ فَاطْلُبْ حَظَّکَ مِنْهَا بِإِجْمَالِ اَلطَّلَبِ\nدنیا دست بدست میچرخد تو بهره خود را از آن با آرامی‌ جستجو کن و حریص مباش.\n✍️ کسانی که میخواهند هیجانی و بیش از حد از دنیا بهره ببرند، دنیا متوجه میشود و با آنها گلاویز میشود. ولی کسانی که آهسته به سراغ دنیا میروند، میتوانند همه بهره شان را بی درد سر از دنیا بگیرند.\n✳️اجمال فی الطلب در سیره امیرالمومنین:\nدرنامه ۴۵ به عثمان بن حنیب:\nوَ لَوْ شِئْتُ لاَهْتَدَیْتُ اَلطَّرِیقَ إِلَى مُصَفَّى هَذَا اَلْعَسَلِ وَ لُبَابِ هَذَا اَلْقَمْحِ وَ نَسَائِجِ هَذَا اَلْقَزِّ  \nفکر نکنید من قادر به تحصیل لذت هاى دنیا نیستم. به خدا سوگند اگر مى خواستم مى توانستم از عسل مصفا و مغز گندم و بافته هاى ابریشم براى خود بهترین غذا و لباس را تهیّه کنم\nوَ لَکِنْ هَیْهَاتَ أَنْ یَغْلِبَنِی هَوَایَ وَ یَقُودَنِی جَشَعِی إِلَى تَخَیُّرِ اَلْأَطْعِمَهِ\nاما هیهات که هواى نفس بر من چیره شود و حرص و طمع مرا وادار به انتخاب طعام هاى لذیذ نماید.\n✍️ حضرت میتوانست بهترین ها را داشته باشد، آن هم از راه حلال و درست ولی اراده کرد میانه روی و زهد در مسیر دنیا را در پیش بگیرد.\n✅نکته:\nباید در به دست آوردن دنیا، زیبایی را لحاظ کرد:\nاگر چه در ابتدای بحث بیان شد که در این حکمت اجمال را به معنای اعتدال میگیریم؛ ولی نباید غافل بود که از جهت لغوی این لفظ به معنای زیبایی است؛ پس باید در طلب دنیا، دنیا طلب زیبا بود.\nکسب زیبا به معنای تلاش برای به دست آوردن روزی از راه‌های حلال، معقول، و با حفظ کرامت انسانی است.\nاین نوع کسب، تنها برای انباشت ثروت نیست، بلکه برای تأمین نیازهای مشروع خود و خانواده، استقلال اقتصادی و قوت گرفتن برای عبادت خداوند است.\n✳️مال حلال، زیبا است:\nکسب وکار و در آمدتان و رزق و روزیتان زیبا باشد. از جایی پول به دست آورید که زیبا باشد. طوری خرج کنید که زیبا باشد.هرکاری که باعث زشتی میشود از خودتان دور کنید.هرمدل پول به دست آوردن که زشت است از تو باید دور باشد. محرمات، مکاسب محرمه زشت است ربا، قمار،زشت است دنبالشان نروید.هرچیزی که زشت باشد دراین دایره جایی ندارد.حضرت فرمودند کار کنیدوظیفه تان است ولی پول قشنگ به دست بیارید.\nقرآن کریم میفرماید:\nیَا أَیُّهَا النَّاسُ کُلُوا مِمَّا فِی الْأَرْضِ حَلَالًا طَیِّبًا\nای مردم! از آنچه در زمین است حلال و پاکیزه بخورید.\n❇️تجارت، بعد از انجام تکالیف عبادی زیباست:\nقرآن کریم در سوره جمعه میفرماید: فَإِذَا قُضِیَتِ الصَّلَاهُ فَانْتَشِرُوا فِی الْأَرْضِ وَابْتَغُوا مِنْ فَضْلِ اللَّهِ\nپس هنگامی که نماز اتمام یافت، در زمین پراکنده شوید و از فضل خدا روزی بجویید.\n⏪پول زیبا پولی است که شما وظیفه ی شرعیتان را انجام بدهیدحالا دنبال کاربردی کاریه انجام می‌دهید پولش زیباست پولش تربیت فرزند شما را به درستی انجام میدهد.\n✍️ این آیه الگویی زیبا ارائه می‌دهد.\nاولویت با عبادت است و سپس تلاش برای روزی در چارچوب رضایت خدا.\n✅کسب در آمدی که با یاد خدا باشد زیباست:\nقرآن کریم در سوره نور میفرماید: رِجَالٌ لَّا تُلْهِیهِمْ تِجَارَهٌ وَلَا بَیْعٌ عَن ذِکْرِ اللَّهِ  \nمردانی که هیچ تجارت و خرید و فروشی آنان را از یاد خدا غافل نمی‌کند…\n◀️کاری که همراه باذکرباشد.پول به دست آوردن که همره با توجه به خدا باشد میشود پول به دست آوردن زیبا\n✍️ نمیفرماید آنها اهل کار نیستند، میفرماید کار آنها را از ذکر و یاد خدا غافل نمیکند.\n✳️رزقی که از طریق جوانمردان برسد زیباست:\nباجوانمردها معاشرت کنید.باجوانمردها دادو ستد کنید.\nحکمت ۶۶:\nفَوْتُ الْحَاجَهِ، أَهْوَنُ مِنْ طَلَبِهَا إِلَى غَیْرِ أَهْلِهَا\nاز دست رفتن حاجت بهتر از طلب کردن آن از نااهلان است!\n⏪اگر می‌خواهید پول زیبا داشته باشید قرضم که خواستید بگیرید از یک انسان جوانمرد بگیرید ولی اگر حق خودتان را از ناجوانمرد گرفتید این به آن زیبایی که باید باشد نیست.\n✅رزقی که دسترنج باشد، زیباست:\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nأطیَبُ الکَسبِ عَمَلُ الرجُلِ بیَدِهِ\nپاکترین کسب و درآمد، دسترنج آدمى است.\n🔺در روایت آمده است: از معجزه زیباتر، کار کردن است:\n📚مرحوم مجلسی در بحار نقل میکند:\nرُویَ أنَّ حَوارِیِّی عیسى علیه السلام کانوا إذا جاعُوا قالوا : یا رُوحَ اللّه جُعْنا ، فَیَضرِبُ بیَدِهِ علَى الأرضِ ـ\nروایت شده است که حواریان عیسى علیه السلام هر گاه گرسنه مى شدند، مى گفتند: یا روح اللّه ! گرسنه شده ایم. پس، عیسى علیه السلام با دست خود به زمین، چه دشت بود و چه کوه، مى زد و براى هر یک از حواریان دو گرده نان بیرون مى آورد، که آنها را مى خوردند.\nفإذا عَطِشُوا قالوا : یا رُوحَ اللّه عَطِشْنا ، فَیَضرِبُ بیَدِهِ على الأرضِ ـ سَهلاً کان أو جَبَلاً ـ فَیُخرِجُ ماءً فَیَشرَبُونَ  \nو هر گاه تشنه مى شدند، مى گفتند: یا روح اللّه ! تشنه شده ایم و آن حضرت با دستش به زمین، خواه دشت بود یا کوه، مى زد و آب بیرون مى آورد و حواریان مى نوشیدند..\nقالوا : یا رُوحَ اللّه ، مَن أفضَلُ مِنّا ؟ إذا شِئنا أطعَمتَنا ، و إذا شِئنا سَقَیتَنا ، و قد آمَنّا بکَ و اتَّبَعناکَ !\nآنها گفتند: یا روح اللّه ! چه کسى از ما برتر است که هر گاه مى خواهیم غذایمان مى دهى و هر گاه مى خواهیم آبمان مى نوشانى در حالى که همه ما به تو ایمان آورده ایم و پیرویت مى کنیم؟\n قالَ : أفضَلُ مِنکُم مَن یَعَملُ بیَدِهِ ، و یَأکُلُ مِن کَسبِهِ  \nعیسى علیه السلام فرمود: برتر از شما، کسى است که با دست خود کار کند و از کسب خودش بخورد.\nفصاروا یَغسِلُونَ الثِّیابَ بالکِراءِ\nاز آن پس حواریان رخت مى شستند و اجرت مى گرفتند.\n✍️پولی که از دسترنج انسان باشد زیباست ولی پولی که باد آورده باشدزیبایی ندارد.\n✳️ رزقی که انسان برای آن  جانش را به خطر نیندازد زیباست:\nمصداقش را درروایات داریم\nامیرالمومنین علیه السلام:\nمَا أَجْمَلَ فِی اَلطَّلَبِ مَنْ رَکِبَ اَلْبَحْرَ لِلتِّجَارَهِ.\nکسی که برای تجارت از راه دریا اقدام کند، در کسب روزی اعتدال به خرج نداده است\n✍️ در گذشته سفرهای دریایی سخت و خطرناک بود، ماهها می رفتند و زن و فرزند، در انتظار و دلهره بودند. حضرت می فرماید این سفرها برای کسب در آمد مناسب نیست.\n❇️رزقی که در وطن به دست بیاید زیباست:\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nأربَعهٌ مِن سَعادَهِ المَرءِ .\nچهار چیز از خوشبختى مرد است\nالخُلَطاءُ الصّالِحُونَ\nهمنشینان شایسته\nو الوَلَدُ البارُّ\nفرزند نیکوکار،\nو المَرأهُ المُؤاتِیَهُ\nزن سازگار،\nو أن تَکونَ مَعِیشَتُهُ فی بَلَدِهِ\nو این که محل کسب او در شهر خودش باشد.\n\n✍️ رزق اگر به دست بیاید ولی آبروی انسان را در معرض خطر قرار دهد، زیبا نیست.\n \n✅کسب  در آمد از طریق ریاست طلبی زیبا نیست:!\nامام صادق علیه السلام:\nمَلْعُونٌ مَنْ تَرَأَّسَ\nملعون است کسى‌که ریاست به خود بندد\nمَلْعُونٌ مَنْ هَمَّ بِهَا   \nملعون است کسى‌که دنبال رسیدن به ریاست باشد\nمَلْعُونٌ مَنْ حَدَّثَ بِهَا نَفْسَهُ\nملعون است کسى که به فکر آن باشد.\nدارد درس می‌خواند تا فردا به پست و‌مقامی برسد.پست ومقام و مسئولیت وظیفه است نباید دنبال آن برود پولی هم که از این راه به دست می آورد زیبا نیست.\n🔹 وقتی امیرالمومنین علیه السلام فرزندان عمویش عباس را مسئولیت داد، مالک اشتر اعتراض کرد که اگر قصه فامیل بازی است، چرا ما عثمان را کشتیم.\n🔹حضرت با ملاطفت به مالک فرمود من که فرزندان خودم را به مسئولیت نگمارده ام و علت اینکه به فرزندان عباس مسئولیت دادم این است که اولا افراد شایسته ای هستند، ثانیا در دوران خلفا به آنها ظلم شد، چون فامیل ما بودند، ثالثا اگر کسی بهتر میشناسی بیاور تا جابجا کنم.\nامیرالمومنین علیه‌السلام فرمود:\nاِنِّی سَمِعْتُ اَلْعَبَّاسَ یَطْلُبُ مِنْ رَسُولِ اَللَّهِ صَلَّى اَللَّهُ عَلَیْهِ وَ آلِهِ اَلْإِمَارَهَ مِرَاراً  \nمن مکرر از عمویم عباس شنیدم که از پیامبر طلب مسئولیت میکرد.\nفَقَالَ لَهُ رَسُولُ اَللَّهِ صَلَّى اَللَّهُ عَلَیْهِ وَ آلِهِ یَا عَمِّ إِنَّ اَلْإِمَارَهَ إِنْ طَلَبْتَهَا وُکِّلْتَ إِلَیْهَا وَ إِنْ طَلَبَتْکَ أُعِنْتَ عَلَیْهَا\nپیامبر صلوات الله علیه و آله فرمود ای عمو حکومت را اگر طلب کنی به همان حکومت واگذار میشوی و اگر او تو را طلب کند خداوند در آن کار به تو یاری می‌رساند.\n✍️باید برای به دست آوردن رزق زیبا منتظر بود تا با توجه به تخصص فرد به او پیشنهاد پست و مقامی پیشنهاد بشود، وگرنه کسی که مدام دنبال رسیدن به جایگاه بالایی است آن پولی که بدست می آورد پول زیبایی نیست.\n\nغفر الله لی و لکم، الحمدلله رب العالمین"]});
